import "../models/legal_tip.dart";

class LegalTipsData {
  LegalTipsData._();

  static final List<LegalTip> allTips = [
    LegalTip(id: 1, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۱ — شرکای شرکت تجاری و مفهوم تاجر بودن", content: "شرکای شرکت تجاری، تاجر محسوب نمی‌شوند مگر آنکه شغل معمول آنها شخصاً اعمال تجاری مصرح در ماده ۲ قانون تجارت باشد. انجام اعمال تجاری باید برای خود شخص و به حساب خود وی انجام شود. بنابراین معامله وکیل برای موکل یا مدیر شرکت برای شرکت موجب تاجر شناخته شدن شخص نمی‌شود.", tags: [],),
    LegalTip(id: 2, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۲ — تصدی به حمل‌ونقل", content: "تصدی به حمل‌ونقل به هر طریقی که باشد عمل تجاری ذاتی است. حمل‌ونقل اعم از حمل مسافر یا اشیا تجاری محسوب می‌شود، اما مقررات مواد ۳۷۷ تا ۳۹۳ قانون تجارت ویژه حمل اشیا است.", tags: [],),
    LegalTip(id: 3, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۳ — اعمال تجاری به محض انجام", content: "برخی اعمال به صرف انجام تجاری محسوب می‌شوند؛ مانند:\n\n* دلالی\n* حق‌العمل‌کاری\n* خرید مال منقول به قصد فروش\n* عملیات بانکی\n* عملیات صرافی\n* بیمه", tags: [],),
    LegalTip(id: 4, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۴ — اعمال تجاری در صورت تکرار", content: "برخی اعمال فقط در صورت تکرار تجاری محسوب می‌شوند:\n\n* تصدی به حمل‌ونقل\n* عملیات حراجی\n* نمایشگاه عمومی\n* رساندن ملزومات\n* تأسیس و بهره‌برداری کارخانه", tags: [],),
    LegalTip(id: 5, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۵ — اماره قانونی معاملات تجاری", content: "تمام معاملات تجار تجاری محسوب می‌شود و این یک اماره قانونی است. اثبات غیرتجاری بودن معامله بر عهده کسی است که چنین ادعایی دارد.", tags: [],),
    LegalTip(id: 6, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۶ — معاملات غیرمنقول", content: "معاملات غیرمنقول اصولاً تجاری محسوب نمی‌شوند، حتی اگر توسط تاجر و برای امور تجاری انجام شوند؛ مگر در شرکت‌های ساختمانی که زمین را برای ساخت و فروش خریداری می‌کنند.", tags: [],),
    LegalTip(id: 7, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۷ — ضمانت اجرای نداشتن دفاتر تجاری", content: "ضمانت اجرای نداشتن دفاتر تجاری یا رعایت نکردن مقررات آن:\n\n* جزای نقدی\n* تعیین مالیات به صورت علی‌الرأس", tags: [],),
    LegalTip(id: 8, category: "۱. مبانی حقوق تجارت و اعمال تجاری", title: "نکته ۸ — اعتبار دفاتر تجاری", content: "دفاتر تجاری اگر مطابق مقررات تنظیم شده باشند:\n\n* بین تجار سند محسوب می‌شوند.\n* علیه صاحب دفتر قابل استناد هستند.\n* در مقابل غیرتاجر می‌توانند قرینه محسوب شوند.", tags: [],),
    LegalTip(id: 9, category: "۲. تشکیل شرکت‌ها و شخصیت حقوقی", title: "نکته ۹ — تشکیل شرکت با مسئولیت محدود و تضامنی", content: "در شرکت‌های با مسئولیت محدود، تضامنی، نسبی و مختلط غیرسهامی، شرکت زمانی تشکیل می‌شود که:\n\n* تمام سرمایه نقدی پرداخت شود.\n* سهم‌الشرکه غیرنقدی تقویم و تسلیم گردد.", tags: [],),
    LegalTip(id: 10, category: "۲. تشکیل شرکت‌ها و شخصیت حقوقی", title: "نکته ۱۰ — تشکیل شرکت سهامی", content: "در شرکت سهامی عام:\nپس از قبول کتبی سمت توسط مدیران و بازرسان در مجمع مؤسس، شرکت تشکیل می‌شود.\n\nدر شرکت سهامی خاص:\nاز زمان امضای صورتجلسه ماده ۲۰ لایحه اصلاحی قانون تجارت، شرکت تشکیل شده محسوب می‌شود.", tags: [],),
    LegalTip(id: 11, category: "۲. تشکیل شرکت‌ها و شخصیت حقوقی", title: "نکته ۱۱ — تشکیل شرکت مختلط سهامی", content: "شرکت مختلط سهامی زمانی تشکیل می‌شود که:\n\n* تمام سرمایه تعهد شده باشد.\n* حداقل یک‌سوم آن پرداخت گردد.", tags: [],),
    LegalTip(id: 12, category: "۲. تشکیل شرکت‌ها و شخصیت حقوقی", title: "نکته ۱۲ — آثار شخصیت حقوقی", content: "آثار شخصیت حقوقی شرکت:\n\n* داشتن اقامتگاه\n* داشتن تابعیت\n* استقلال دارایی شرکت از شرکا\n* تفاوت در مدیریت و تصمیم‌گیری", tags: [],),
    LegalTip(id: 13, category: "۳. اساسنامه، سهام و حقوق سهامداران", title: "نکته ۱۳ — جایگاه اساسنامه", content: "اساسنامه طبق ماده ۸ لایحه اصلاحی قانون تجارت در حکم قانون اداره شرکت است و در شرکت‌های سهامی وجود آن الزامی است.", tags: [],),
    LegalTip(id: 14, category: "۳. اساسنامه، سهام و حقوق سهامداران", title: "نکته ۱۴ — انتقال سهام", content: "اساسنامه نمی‌تواند برخلاف مقررات قانونی برای انتقال سهام محدودیت ایجاد کند.\n\nنکات مهم:\n\n* ثبت انتقال سهام بانام در دفتر سهام الزامی است.\n* در شرکت سهامی عام انتقال سهام نمی‌تواند منوط به موافقت مدیران یا مجمع باشد.", tags: [],),
    LegalTip(id: 15, category: "۳. اساسنامه، سهام و حقوق سهامداران", title: "نکته ۱۵ — محدود کردن اختیارات مدیران", content: "محدود کردن اختیارات مدیران:\n\n* فقط بین مدیران و سهامداران معتبر است.\n* در برابر اشخاص ثالث باطل و بلااثر است.", tags: [],),
    LegalTip(id: 16, category: "۳. اساسنامه، سهام و حقوق سهامداران", title: "نکته ۱۶ — دعوای مسئولیت علیه مدیران", content: "اساسنامه یا تصمیمات مجامع نمی‌توانند:\n\n* حق اقامه دعوی علیه مدیران را محدود کنند.\n* مدیران را از مسئولیت معاف نمایند.", tags: [],),
    LegalTip(id: 17, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۱۷ — دعوت مجمع مؤسس", content: "پس از پذیره‌نویسی، مؤسسین باید مجمع مؤسس را دعوت کنند.\n\nاگر از دعوت خودداری کنند:\n\n* الزام آنان ممکن نیست.\n* اما در برابر خسارات وارده مسئولیت تضامنی دارند.", tags: [],),
    LegalTip(id: 18, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۱۸ — وظایف مجمع مؤسس", content: "وظایف مجمع مؤسس:\n\n* تصویب اساسنامه\n* انتخاب مدیران\n* انتخاب بازرسان\n\nمدیران و بازرسان باید کتبی سمت را بپذیرند.", tags: [],),
    LegalTip(id: 19, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۱۹ — حد نصاب حضور", content: "* نوبت اول: حضور حداقل نصف سرمایه\n* نوبت دوم: حضور حداقل یک‌سوم سرمایه", tags: [],),
    LegalTip(id: 20, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۲۰ — حد نصاب تصمیم‌گیری", content: "تصمیمات با اکثریت دوسوم آرای حاضر معتبر است.", tags: [],),
    LegalTip(id: 21, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۲۱ — حق رأی", content: "در مجمع مؤسس:\n\n* همه مؤسسین و پذیره‌نویسان حق رأی دارند.\n* هر سهم یک رأی دارد.", tags: [],),
    LegalTip(id: 22, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۲۲ — مسئولیت تضامنی مؤسسین", content: "مؤسسین نسبت به تمام اعمال مربوط به تأسیس شرکت مسئولیت تضامنی دارند.", tags: [],),
    LegalTip(id: 23, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۲۳ — ممنوعیت‌های شرکت قبل از ثبت", content: "قبل از ثبت شرکت:\n\n* برداشت وجوه بانکی ممنوع است.\n* صدور سهام ممنوع است.\n* صدور گواهی موقت سهم ممنوع است.\n* صدور اوراق قرضه ممنوع است.\n* صدور اوراق مشارکت ممنوع است.", tags: [],),
    LegalTip(id: 24, category: "۴. مجمع عمومی مؤسس و تأسیس شرکت سهامی", title: "نکته ۲۴ — انتشار اوراق قرضه", content: "انتشار اوراق قرضه فقط زمانی ممکن است که:\n\n* کل سرمایه پرداخت شده باشد.\n* دو سال از ثبت شرکت گذشته باشد.\n* دو ترازنامه به تصویب مجمع رسیده باشد.", tags: [],),
    LegalTip(id: 25, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۲۵ — مفهوم مجمع عمومی فوق‌العاده", content: "مجمع عمومی فوق‌العاده برای رسیدگی به امور مهم و فوق‌العاده شرکت تشکیل می‌شود؛ اموری که نیاز به تغییر یا اصلاح اساسنامه دارند.", tags: [],),
    LegalTip(id: 26, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۲۶ — وظایف مجمع عمومی فوق‌العاده", content: "وظایف این مجمع:\n\n* تغییر مواد اساسنامه\n* افزایش یا کاهش سرمایه\n* انحلال پیش از موعد\n* ایجاد سهام ممتاز\n* اعطای اجازه انتشار اوراق قرضه\n* تبدیل شرکت سهامی عام به خاص\n* تبدیل سهام بانام به بی‌نام و بالعکس", tags: [],),
    LegalTip(id: 27, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۲۷ — محدودیت‌های مجمع عمومی فوق‌العاده", content: "این مجمع نمی‌تواند:\n\n* تابعیت شرکت را تغییر دهد.\n* تعهدات سهامداران را افزایش دهد مگر با رضایت همه سهامداران.\n* حقوق قانونی سهامداران را از بین ببرد.", tags: [],),
    LegalTip(id: 28, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۲۸ — حد نصاب حضور در مجمع فوق‌العاده", content: "* مرحله اول: حضور دارندگان بیش از نصف سهام دارای حق رأی\n* مرحله دوم: حضور دارندگان بیش از یک‌سوم سهام دارای حق رأی", tags: [],),
    LegalTip(id: 29, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۲۹ — حد نصاب تصمیم‌گیری", content: "تصمیمات مجمع عمومی فوق‌العاده با اکثریت دوسوم آرای حاضر معتبر است.", tags: [],),
    LegalTip(id: 30, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۳۰ — مفهوم مجمع عمومی عادی", content: "مجمع عمومی عادی درباره تمام امور شرکت صلاحیت تصمیم‌گیری دارد مگر موضوعاتی که در صلاحیت مجامع مؤسس و فوق‌العاده است.\n\nتشکیل این مجمع حداقل سالی یک‌بار الزامی است.", tags: [],),
    LegalTip(id: 31, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۳۱ — وظایف مجمع عمومی عادی", content: "وظایف مهم:\n\n* رسیدگی به سود و زیان\n* تصویب ترازنامه\n* انتخاب و عزل مدیران\n* تصویب معاملات ماده ۱۲۹\n* تقسیم سود\n* تعیین اندوخته", tags: [],),
    LegalTip(id: 32, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۳۲ — حد نصاب حضور در مجمع عادی", content: "* مرحله اول: حضور بیش از نصف سهام دارای حق رأی\n* مرحله دوم: حضور هر تعداد از صاحبان سهام", tags: [],),
    LegalTip(id: 33, category: "۵. مجامع عمومی شرکت سهامی", title: "نکته ۳۳ — حد نصاب تصمیم‌گیری در مجمع عادی", content: "تصمیمات با:\n\n* نصف بعلاوه یک آرای حاضر معتبر است.\n\nاما در انتخاب مدیران و بازرسان:\n\n* اکثریت نسبی ملاک است.", tags: [],),
    LegalTip(id: 34, category: "۶. سرمایه، سهام و اندوخته", title: "نکته ۳۴ — حق تقدم خرید سهام جدید", content: "سهامداران در خرید سهام جدید حق تقدم دارند.\n\nمجمع عمومی فوق‌العاده می‌تواند این حق را سلب کند.\n\nاین حق:\n\n* قابل انتقال است.\n* دارای محدودیت‌های قانونی است.", tags: [],),
    LegalTip(id: 35, category: "۶. سرمایه، سهام و اندوخته", title: "نکته ۳۵ — کاهش اختیاری سرمایه", content: "کاهش اختیاری سرمایه فقط از طریق:\n\n* کاهش بهای اسمی سهام\n* و بازگرداندن مبلغ کاهش یافته به صاحبان سهام\n\nامکان‌پذیر است.", tags: [],),
    LegalTip(id: 36, category: "۶. سرمایه، سهام و اندوخته", title: "نکته ۳۶ — اندوخته قانونی", content: "هیأت مدیره موظف است:\nهر سال یک‌بیستم سود خالص شرکت را به اندوخته قانونی اختصاص دهد تا زمانی که اندوخته به یک‌دهم سرمایه شرکت برسد.\n\nپس از آن:\n\n* اختصاص اندوخته اختیاری می‌شود.", tags: [],),
    LegalTip(id: 37, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۳۷ — موارد مراجعه ذی‌نفع به دادگاه برای انحلال", content: "موارد مهم:\n\n* عدم شروع فعالیت شرکت تا یک سال پس از ثبت\n* توقف فعالیت بیش از یک سال\n* تشکیل نشدن مجمع سالانه تا ده ماه\n* بلاتصدی ماندن سمت مدیران بیش از شش ماه\n\nدادگاه برای رفع مشکل:\n\n* شش ماه مهلت می‌دهد.", tags: [],),
    LegalTip(id: 38, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۳۸ — مسئولیت تصفیه", content: "تصفیه شرکت طبق مقررات قانون تجارت انجام می‌شود و اصولاً بر عهده مدیران شرکت است مگر در ورشکستگی.", tags: [],),
    LegalTip(id: 39, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۳۹ — وظایف مدیران تصفیه", content: "مدیران تصفیه باید هر سال:\n\n* مجمع عمومی عادی تشکیل دهند.\n* صورت دارایی و بدهی ارائه کنند.\n* گزارش عملکرد تصفیه را ارائه نمایند.\n\nدعوی علیه شرکت منحل‌شده:\n\n* تا پایان تصفیه علیه مدیران تصفیه مطرح می‌شود.", tags: [],),
    LegalTip(id: 40, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۴۰ — پایان شخصیت حقوقی", content: "شخصیت حقوقی شرکت:\n\n* با پایان تصفیه از بین می‌رود.", tags: [],),
    LegalTip(id: 41, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۴۱ — محدود کردن اختیارات مدیر تصفیه", content: "محدود کردن اختیارات مدیران تصفیه:\n\n* باطل و بلااثر است.", tags: [],),
    LegalTip(id: 42, category: "۷. انحلال و تصفیه شرکت‌های سهامی", title: "نکته ۴۲ — انتقال دارایی به مدیران تصفیه", content: "انتقال دارایی شرکت به:\n\n* مدیران تصفیه\n* اقوام درجه ۱ و ۲ تا درجه ۴\n\nباطل بوده و جرم محسوب می‌شود.", tags: [],),
    LegalTip(id: 43, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۳ — تقویم آورده غیرنقدی", content: "در شرکت با مسئولیت محدود:\n\n* ارزش‌گذاری آورده غیرنقدی با توافق همه شرکا انجام می‌شود.\n* نیاز به کارشناس رسمی نیست.", tags: [],),
    LegalTip(id: 44, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۴ — قید قیمت آورده غیرنقدی", content: "قیمت آورده غیرنقدی باید در شرکت‌نامه ذکر شود وگرنه:\n\n* شرکت باطل است.", tags: [],),
    LegalTip(id: 45, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۵ — تقویم بیش از ارزش واقعی", content: "اگر آورده غیرنقدی بیش از ارزش واقعی قیمت‌گذاری شود:\n\n* شرکای دخیل به مجازات کلاهبرداری محکوم می‌شوند.", tags: [],),
    LegalTip(id: 46, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۶ — استثنائات مسئولیت محدود", content: "مواردی که مسئولیت شرکا تضامنی می‌شود:\n\n* ذکر نکردن عبارت «با مسئولیت محدود»\n* ذکر نام شریک در نام شرکت\n* پرداخت نشدن سرمایه نقدی\n* تقویم نشدن آورده غیرنقدی", tags: [],),
    LegalTip(id: 47, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۷ — تسلیم آورده‌ها", content: "در شرکت با مسئولیت محدود:\n\n* آورده به مدیرعامل تحویل می‌شود.\n* برخلاف شرکت سهامی نیازی به تودیع در بانک نیست.", tags: [],),
    LegalTip(id: 48, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۸ — انتقال سهم‌الشرکه", content: "سهم‌الشرکه:\n\n* قابل تبدیل به اوراق تجاری نیست.\n* فقط با رضایت اکثریت شرکا ممکن است.\n* باید با سند رسمی انجام شود.", tags: [],),
    LegalTip(id: 49, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۴۹ — مدیر غیرشریک", content: "در شرکت با مسئولیت محدود:\n\n* مدیر می‌تواند شریک نباشد.", tags: [],),
    LegalTip(id: 50, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۰ — شرکت‌هایی که مدیر لازم نیست شریک باشد", content: "در این شرکت‌ها مدیر لازم نیست شریک باشد:\n\n* تضامنی\n* نسبی\n* با مسئولیت محدود", tags: [],),
    LegalTip(id: 51, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۱ — تشکیل مجمع عمومی", content: "در شرکت با مسئولیت محدود:\n\n* تشکیل مجمع عمومی الزامی نیست.\n\nاما اگر تعداد شرکا بیش از ۱۲ نفر باشد:\n\n* تشکیل مجمع عمومی سالانه الزامی است.", tags: [],),
    LegalTip(id: 52, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۲ — تصمیمات امور جاری", content: "تصمیمات امور جاری:\n\n* در مرحله اول با اکثریت حداقل نصف سرمایه\n* و در مرحله دوم با اکثریت عددی شرکا\n\nاتخاذ می‌شود مگر اساسنامه اکثریت بیشتری مقرر کرده باشد.", tags: [],),
    LegalTip(id: 53, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۳ — موارد تصمیمات جاری", content: "این تصمیمات شامل:\n\n* انتخاب مدیران\n* عزل مدیران\n* انتخاب بازرس\n* عزل بازرس\n* انتخاب مدیر تصفیه\n* اعطای اختیار سازش یا ارجاع دعاوی\n\nاست.", tags: [],),
    LegalTip(id: 54, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۴ — تغییر اساسنامه و انتقال سهم‌الشرکه", content: "تصمیمات مربوط به:\n\n* تغییر اساسنامه\n* انتقال سهم‌الالشرکه\n\nنیازمند:\n\n* اکثریت عددی شرکا\n* و مالکیت حداقل سه‌چهارم سرمایه\n\nاست.", tags: [],),
    LegalTip(id: 55, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۵ — انحلال شرکت", content: "تصمیم‌گیری درباره انحلال شرکت:\n\n* با موافقت دارندگان بیش از نصف سرمایه ممکن است.", tags: [],),
    LegalTip(id: 56, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۶ — تشکیل هیأت نظار", content: "اگر تعداد شرکا بیش از ۱۲ نفر باشد:\n\n* تشکیل هیأت نظار الزامی است.\n\nهیأت نظار:\n\n* باید از بین شرکا انتخاب شود.", tags: [],),
    LegalTip(id: 57, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۷ — موارد انحلال", content: "موارد انحلال شرکت با مسئولیت محدود:\n\n* انجام شدن موضوع شرکت\n* منتفی شدن موضوع شرکت\n* پایان مدت شرکت\n* ورشکستگی\n* تصمیم شرکای دارای بیش از نصف سرمایه\n* از بین رفتن نصف سرمایه\n* فوت شریک در صورت پیش‌بینی در اساسنامه", tags: [],),
    LegalTip(id: 58, category: "۸. شرکت با مسئولیت محدود", title: "نکته ۵۸ — عدم امکان درخواست انحلال توسط طلبکاران", content: "در شرکت با مسئولیت محدود:\n\n* طلبکاران و اشخاص ذی‌نفع حق درخواست انحلال ندارند.", tags: [],),
    LegalTip(id: 59, category: "۹. شرکت تضامنی و مسئولیت شرکا", title: "نکته ۵۹ — ممنوعیت رقابت", content: "در شرکت تضامنی:\n\n* شرکا بدون اجازه سایر شرکا حق رقابت با شرکت را ندارند.\n\nدر شرکت سهامی:\n\n* فقط اعضای هیأت مدیره و مدیرعامل ممنوع از رقابت هستند.", tags: [],),
    LegalTip(id: 60, category: "۹. شرکت تضامنی و مسئولیت شرکا", title: "نکته ۶۰ — مسئولیت تضامنی", content: "مسئولیت شرکا در برابر طلبکاران:\n\n* تضامنی است.\n* توافق برخلاف آن در برابر اشخاص ثالث بی‌اثر است.", tags: [],),
    LegalTip(id: 61, category: "۹. شرکت تضامنی و مسئولیت شرکا", title: "نکته ۶۱ — شرایط تشکیل شرکت تضامنی", content: "شرکت تضامنی زمانی تشکیل می‌شود که:\n\n* سرمایه نقدی پرداخت شود.\n* آورده غیرنقدی تقویم و تسلیم گردد.\n\nدر غیر این صورت:\n\n* شرکت باطل است.\n\nاما شرکا نمی‌توانند به این بطلان در برابر اشخاص ثالث استناد کنند.", tags: [],),
    LegalTip(id: 62, category: "۹. شرکت تضامنی و مسئولیت شرکا", title: "نکته ۶۲ — مسئولیت شرکت در صدور برات", content: "اگر مدیر شرکت بیش از اختیارات خود برات صادر کند:\n\n* ممکن است شخصاً مسئول شناخته شود.\n\nدر شرکت سهامی:\n\n* حتی در صورت تجاوز از اختیار، شرکت مسئول پرداخت است.", tags: [],),
    LegalTip(id: 63, category: "۱۰. برات و مقررات آن", title: "نکته ۶۳ — مسئولیت براتگیر", content: "براتگیری که برات را قبول کرده:\n\n* مدیون اصلی محسوب می‌شود.\n* موظف به پرداخت وجه برات است.", tags: [],),
    LegalTip(id: 64, category: "۱۰. برات و مقررات آن", title: "نکته ۶۴ — دارنده بودن براتکش", content: "اگر دارنده برات خود براتکش باشد:\n\n* مسئولیت براتگیر مطلق نیست.", tags: [],),
    LegalTip(id: 65, category: "۱۰. برات و مقررات آن", title: "نکته ۶۵ — ایراد عدم مدیونیت", content: "اگر براتکش محل برات را تأمین نکرده باشد:\n\n* براتگیر می‌تواند به عدم مدیونیت استناد کند.", tags: [],),
    LegalTip(id: 66, category: "۱۰. برات و مقررات آن", title: "نکته ۶۶ — اعلام اعتراض", content: "دارنده برات باید ظرف ۱۰ روز:\n\n* اعتراض عدم تأدیه را اعلام کند.", tags: [],),
    LegalTip(id: 67, category: "۱۰. برات و مقررات آن", title: "نکته ۶۷ — نظر دیوان عالی کشور", content: "دیوان عالی:\n\n* مواعد مواد ۲۸۶ و ۲۸۷ را مربوط به اقامه دعوی دانسته\n* نه مهلت ده‌روزه ارسال اظهارنامه.", tags: [],),
    LegalTip(id: 68, category: "۱۰. برات و مقررات آن", title: "نکته ۶۸ — مسئولیت قبولی و پرداخت", content: "مسئولیت صادرکننده:\n\n* مسئولیت قبولی\n* و مسئولیت پرداخت\n\nرا شامل می‌شود.", tags: [],),
    LegalTip(id: 69, category: "۱۰. برات و مقررات آن", title: "نکته ۶۹ — اصل بر عدم تأمین محل برات", content: "اصل بر این است که:\n\n* صادرکننده محل برات را تأمین نکرده\n  مگر خلاف آن ثابت شود.", tags: [],),
    LegalTip(id: 70, category: "۱۰. برات و مقررات آن", title: "نکته ۷۰ — وظایف دارنده", content: "وظایف دارنده:\n\n* اعتراض عدم تأدیه\n* اقامه دعوی در مهلت قانونی\n\nدر صورت عدم رعایت:\n\n* حق رجوع به ظهرنویسان از بین می‌رود.", tags: [],),
    LegalTip(id: 71, category: "۱۰. برات و مقررات آن", title: "نکته ۷۱ — دارنده کاهل", content: "دارنده‌ای که مواعد قانونی را رعایت نکند:\n\n* دارنده کاهل نامیده می‌شود.", tags: [],),
    LegalTip(id: 72, category: "۱۰. برات و مقررات آن", title: "نکته ۷۲ — رد پرداخت ثالث", content: "اگر دارنده پرداخت ثالث را رد کند:\n\n* حق رجوع به برخی مسئولان را از دست می‌دهد.", tags: [],),
    LegalTip(id: 73, category: "۱۱. سفته و چک", title: "نکته ۷۳ — وظایف دارنده سفته", content: "دارنده سفته موظف است:\n\n* ظرف ۱۰ روز اعتراض عدم تأدیه انجام دهد.\n* در سفته عندالمطالبه ظرف یک سال اقدام مقتضی انجام دهد.\n* ظرف مواعد قانونی اقامه دعوی نماید.", tags: [],),
    LegalTip(id: 74, category: "۱۱. سفته و چک", title: "نکته ۷۴ — وظایف دارنده چک", content: "وظایف دارنده چک:\n\n* اخذ گواهی عدم پرداخت در مواعد قانونی\n* اقامه دعوی در مهلت مقرر\n\nدر صورت عدم رعایت:\n\n* حق رجوع به ظهرنویسان از بین می‌رود.", tags: [],),
    LegalTip(id: 75, category: "۱۱. سفته و چک", title: "نکته ۷۵ — چک به عنوان سند لازم‌الاجرا", content: "چک در حکم سند لازم‌الاجرا است و می‌توان علیه صادرکننده:\n\n* از طریق اجرای ثبت\n* تقاضای صدور اجرائیه نمود.\n\nمشروط بر:\n\n* تأیید امضا توسط بانک\n* وجود مال از صادرکننده", tags: [],),
    LegalTip(id: 76, category: "۱۱. سفته و چک", title: "نکته ۷۶ — مزایای چک", content: "مزایای چک:\n\n* امکان تأمین خواسته\n* قابلیت تعقیب کیفری\n* امکان اجرا از طریق ثبت اسناد", tags: [],),
    LegalTip(id: 77, category: "۱۱. سفته و چک", title: "نکته ۷۷ — موارد غیرقابل تعقیب کیفری", content: "این چک‌ها قابل تعقیب کیفری نیستند:\n\n* چک سفیدامضا\n* چک مشروط\n* چک امانی\n* چک تضمینی\n* چک وعده‌دار\n* چک بدون تاریخ", tags: [],),
    LegalTip(id: 78, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۷۸ — ماهیت قرارداد دلالی", content: "دلالی:\n\n* عقدی معوض است.\n* عدم تعیین اجرت موجب بطلان آن نمی‌شود.\n* در صورت سکوت، دلال مستحق اجرت‌المثل است.", tags: [],),
    LegalTip(id: 79, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۷۹ — مسئولیت دلال نسبت به اسناد", content: "دلال زمانی مسئول صحت امضاهاست که:\n\n* معامله به واسطه او انجام شده باشد.\n* اسناد از طریق دلال مبادله شده باشد.\n* امضاها مربوط به طرفین معامله باشد.", tags: [],),
    LegalTip(id: 80, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۸۰ — مسئولیت دلال نسبت به طرفین معامله", content: "دلال:\n\n* ضامن اعتبار اشخاص نیست.\n* مسئول اجرای تعهدات طرف مقابل نیست.\n  مگر آنکه ضمانت کرده باشد.", tags: [],),
    LegalTip(id: 81, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۸۱ — حق حبس دلال", content: "دلال نسبت به:\n\n* مال موضوع معامله\n* اسناد نزد خود\n\nحق حبس ندارد.", tags: [],),
    LegalTip(id: 82, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۸۲ — نمایندگی ناقص", content: "در حق‌العمل‌کاری:\n\n* حق‌العمل‌کار ابتدا خود طرف قرارداد می‌شود.\n* سپس حقوق و تعهدات را به آمر منتقل می‌کند.", tags: [],),
    LegalTip(id: 83, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۸۳ — قرارداد به نام خود", content: "حق‌العمل‌کار:\n\n* قرارداد را به نام خود منعقد می‌کند.\n* شخصاً در برابر طرف قرارداد مسئول است.", tags: [],),
    LegalTip(id: 84, category: "۱۲. دلالی و حق‌العمل‌کاری", title: "نکته ۸۴ — مسئولیت در برابر آمر", content: "حق‌العمل‌کار:\n\n* مسئول اجرای تعهدات طرف مقابل نیست.\n  مگر:\n* ضمانت کرده باشد\n* یا عرف تجاری چنین اقتضا کند.", tags: [],),
    LegalTip(id: 85, category: "۱۳. حمل‌ونقل تجاری", title: "نکته ۸۵ — موارد معافیت از مسئولیت", content: "متصدی حمل در موارد زیر مسئول نیست:\n\n* عیب ذاتی کالا\n* تقصیر فرستنده یا گیرنده\n* دستور فرستنده یا گیرنده\n* حوادث قهری و غیرقابل پیشگیری", tags: [],),
    LegalTip(id: 86, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۸۶ — تکلیف تاجر پس از توقف", content: "تاجر باید ظرف سه روز از توقف:\n\n* توقف خود را اعلام کند.\n* دفاتر و صورت دارایی را به دادگاه ارائه دهد.\n\nعدم انجام این تکلیف:\n\n* می‌تواند موجب ورشکستگی به تقصیر شود.", tags: [],),
    LegalTip(id: 87, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۸۷ — موارد ورشکستگی به تقصیر اجباری", content: "موارد مهم:\n\n* ولخرجی غیرمتعارف\n* معاملات پرریسک غیرمنطقی\n* خرید گران یا فروش ارزان برای پنهان کردن بحران\n* ترجیح برخی طلبکاران پس از توقف", tags: [],),
    LegalTip(id: 88, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۸۸ — موارد ورشکستگی به تقصیر اختیاری", content: "موارد:\n\n* قبول تعهدات بدون عوض\n* اعلام نکردن توقف با سوءنیت\n* نداشتن دفاتر یا ناقص بودن آنها", tags: [],),
    LegalTip(id: 89, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۸۹ — مخفی کردن دارایی", content: "مخفی کردن اموال توسط تاجر:\n\n* ورشکستگی به تقلب محسوب می‌شود.", tags: [],),
    LegalTip(id: 90, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۹۰ — افزایش متقلبانه بدهی", content: "بیشتر نشان دادن بدهی‌ها:\n\n* برای کاهش سهم طلبکاران\n* ورشکستگی به تقلب است.", tags: [],),
    LegalTip(id: 91, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۹۱ — از بین بردن دارایی توسط بستگان", content: "اگر بستگان دارایی تاجر را مخفی یا نابود کنند:\n\n* ممکن است مشمول مجازات کیفری شوند.", tags: [],),
    LegalTip(id: 92, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۹۲ — خسارت تأخیر تأدیه", content: "طلبکاران پس از تاریخ توقف:\n\n* حق مطالبه خسارت تأخیر تأدیه ندارند.", tags: [],),
    LegalTip(id: 93, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۹۳ — شرایط تشکیل قرارداد ارفاقی", content: "برای تشکیل قرارداد ارفاقی:\n\n* حضور تاجر\n* عضو ناظر\n* اکثریت طلبکاران\n\nضروری است.", tags: [],),
    LegalTip(id: 94, category: "۱۴. ورشکستگی و تصفیه تاجر", title: "نکته ۹۴ — قرارداد ارفاقی و ورشکستگی به تقلب", content: "با تاجری که:\n\n* فقط تحت تعقیب است\n  می‌توان قرارداد ارفاقی بست.\n\nاما با تاجری که:\n\n* محکوم شده\n  نمی‌توان.", tags: [],),
