  static bool isFavorite(int id) => _favoriteTipIds.contains(id);

  static void toggleFavorite(int id) {
    if (_favoriteTipIds.contains(id)) {
      _favoriteTipIds.remove(id);
    } else {
      _favoriteTipIds.add(id);
    }
  }
